package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import java.math.*;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Published cost/capital budgets and cash plans are separate controls. No budget amount is an accounting fact. */
final class FinanceBudgetControl {
 private final NamedParameterJdbcTemplate jdbc;private final FinanceControlGuard guard;
 FinanceBudgetControl(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;guard=new FinanceControlGuard(jdbc);}
 void reserve(TenantPrincipal p,String kind,Map<String,Object> source){if(!guard.installed())return;jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,103))",base(p).addValue("key",p.tenantId()+":financial-budget"),Object.class);UUID hotel=id(source.get("hotel_id")),sourceId=id(source.get("id"));
  var dimensions=new FinanceBudgetDimensions(jdbc);boolean dimensional=dimensions.installed();var lines=new ArrayList<Map<String,Object>>();if(kind.equals("CLAIM")){lines.addAll(jdbc.queryForList("select category_id,department_id,allocation_month,amount,treatment"+(dimensional?",project_key,project_snapshot,financial_category_code":"")+" from finance_claim_line where tenant_id=:tenant and claim_id=:id",base(p).addValue("id",sourceId)));if(lines.isEmpty())lines.add(new LinkedHashMap<>(Map.of("category_id",source.get("category_id"),"allocation_month",source.get("business_date"),"amount",source.get("requested_amount"),"treatment",source.get("treatment"))));}
  else{if(dimensional){UUID company=jdbc.queryForObject("select company_id from fo_document where tenant_id=:tenant and id=:id",base(p).addValue("id",sourceId),UUID.class);new FinanceProjectDimensions(jdbc,new cn.sifangguan.hotelaios.shared.security.AccessPolicy()).verifyFrozen(p,hotel,company,map(source.get("details")));}if(source.get("recognized_source_document_id")!=null||"FS_PROCUREMENT".equals(source.get("source_type")))return;String type=Objects.toString(source.get("type"));String treatment=type.equals("ASSET")?"ASSET":type.equals("PREPAYMENT")?"PREPAID":Objects.toString(map(source.get("details")).get("treatment"),"");if(!Set.of("EXPENSE","ASSET","INVENTORY").contains(treatment))return;
   for(var row:rows(source.get("lines"))){var line=new LinkedHashMap<String,Object>();line.put("code",row.get("categoryCode"));line.put("department_id",row.get("departmentId"));line.put("allocation_month",source.get("business_date"));line.put("amount",amount(row.get("quantity")).multiply(amount(row.get("unitPrice"))).setScale(2,RoundingMode.HALF_UP));line.put("treatment",treatment);line.put("project_key",Objects.toString(map(source.get("details")).get("projectKey"),"NONE"));line.put("project_snapshot",map(source.get("details")).get("projectSnapshot"));lines.add(line);}}
  var policies=jdbc.queryForList("select * from fc_policy where tenant_id=:tenant and hotel_id=:hotel and kind='BUDGET' and status='PUBLISHED' order by id for update",base(p).addValue("hotel",hotel));
  for(var policy:policies){var spec=map(policy.get("spec"));String code=Objects.toString(spec.get("categoryCode"));UUID category=dimensional?id(dimensions.category(p,hotel,spec,false).get("id")):spec.get("categoryId")!=null?id(spec.get("categoryId")):UUID.nameUUIDFromBytes((p.tenantId()+":"+hotel+":category:"+code).getBytes(java.nio.charset.StandardCharsets.UTF_8));String projectKey=dimensional?dimensions.frozenProjectKey(p,hotel,spec):"ALL";String budgetMonth=spec.get("month").toString(),budgetKind=Objects.toString(spec.get("budgetKind"));BigDecimal used=BigDecimal.ZERO;
   for(var line:lines){LocalDate day=LocalDate.parse(line.get("allocation_month").toString());String treatment=Objects.toString(line.get("treatment"));if(!YearMonth.from(day).toString().equals(budgetMonth)||!Objects.equals(kind.equals("CLAIM")?category:code,kind.equals("CLAIM")?line.get("category_id"):line.get("code")))continue;
    if(!Objects.toString(spec.get("departmentId"),"").isBlank()&&!Objects.toString(spec.get("departmentId")).equals(Objects.toString(line.get("department_id"),"")))continue;
    if(dimensional&&!Set.of("ALL","NONE").contains(projectKey)&&Objects.toString(line.get("project_key"),"NONE").equals("NONE")&&!"EXPLICIT_NONE".equals(map(line.get("project_snapshot")).get("designation")))throw conflict("同类别、月份和部门的原单尚未核实项目，不能按零项目占用放行；请在未冻结草稿明确选择，已冻结历史请采用独立确认的总预算或下一期启用项目预算");
    if(!projectKey.equals("ALL")&&!projectKey.equals(Objects.toString(line.get("project_key"),"NONE")))continue;
    if(budgetKind.equals("EXPENSE")&&!treatment.equals("EXPENSE")||budgetKind.equals("CAPITAL")&&!treatment.equals("ASSET")||budgetKind.equals("INVENTORY")&&!treatment.equals("INVENTORY"))continue;
    LocalDate start=LocalDate.parse(policy.get("effective_from").toString()),end=policy.get("effective_to")==null?LocalDate.MAX:LocalDate.parse(policy.get("effective_to").toString());if(!day.isBefore(start)&&!day.isAfter(end))used=used.add(amount(line.get("amount")));
   }
   if(used.signum()==0)continue;var b=base(p).addValue("policy",policy.get("id")).addValue("kind",kind).addValue("source",sourceId).addValue("hotel",hotel).addValue("code",policy.get("code")).addValue("month",budgetMonth);BigDecimal occupied=jdbc.queryForObject("select coalesce(sum(u.amount),0) from fc_budget_usage u join fc_policy p on p.tenant_id=u.tenant_id and p.id=u.policy_id where u.tenant_id=:tenant and p.hotel_id=:hotel and p.kind='BUDGET' and p.code=:code and p.spec->>'month'=:month and u.state<>'RELEASED' and not(u.source_kind=:kind and u.source_id=:source)",b,BigDecimal.class);boolean exceeded=occupied.add(used).compareTo(amount(spec.get("amount")))>0;
   if(guard.table("fbu_flow")){String department=Objects.toString(spec.get("departmentId"),"");b.addValue("monthDate",YearMonth.parse(budgetMonth).atDay(1)).addValue("categoryCode",code).addValue("basisKind",budgetKind).addValue("allDepartments",department.isBlank()).addValue("department",department.isBlank()?null:UUID.fromString(department));if(dimensional&&!Set.of("ALL","NONE").contains(projectKey)){BigDecimal unknown=jdbc.queryForObject("select coalesce(sum(inflight+committed+actual+case when basis_kind='INVENTORY' then inventory_value else 0 end),0) from fbu_flow where tenant_id=:tenant and hotel_id=:hotel and month=:monthDate and category_code=:categoryCode and basis_kind=:basisKind and (:allDepartments or department_id=:department) and project_kind='NONE' and coalesce(project_snapshot->>'designation','')<>'EXPLICIT_NONE'",b,BigDecimal.class);if(unknown.signum()!=0)throw conflict("同类别、月份和部门存在历史未核项目的实际预算占用，不能过滤后当作零；已冻结来源不可直接改写，请独立确认总预算或下一期启用项目预算");}BigDecimal bridged=jdbc.queryForObject("select coalesce(sum(inflight+committed+actual+case when basis_kind='INVENTORY' then inventory_value else 0 end),0) from fbu_flow where tenant_id=:tenant and hotel_id=:hotel and month=:monthDate and category_code=:categoryCode and basis_kind=:basisKind and (:allDepartments or department_id=:department)"+(dimensional?" and (:allProjects or project_key=:projectKey)":""),b.addValue("allProjects",projectKey.equals("ALL")).addValue("projectKey",projectKey),BigDecimal.class);occupied=occupied.add(bridged);exceeded=occupied.add(used).compareTo(amount(spec.get("amount")))>0;}
   if(exceeded&&"BLOCK".equals(spec.get("control"))){boolean exception=guard.table("fc_budget_exception")&&jdbc.queryForObject("select count(*) from fc_budget_exception where tenant_id=:tenant and policy_id=:policy and source_kind=:kind and source_id=:source and source_version=:version and status='APPROVED' and valid_until>statement_timestamp() and ceiling>=:amount",b.addValue("version",source.get("version")).addValue("amount",used),Integer.class)>0;if(!exception)throw conflict("已发布预算超额："+policy.get("title")+"；请先办理独立复核的预算修订或本草稿限额例外，不能从其他入口绕过");guard.event(p,hotel,kind,sourceId,"BUDGET_EXCEPTION_USED",Map.of("policyId",policy.get("id"),"sourceVersion",source.get("version"),"amount",used.toPlainString()));}
   b.addValue("amount",used).addValue("snapshot",json(Map.of("policyId",policy.get("id"),"policyVersion",policy.get("version"),"spec",spec,"overBudget",exceeded,"occupiedBefore",occupied.toPlainString(),"usedAmount",used.toPlainString(),"state","INFLIGHT","occupancyBasis","BUDGET_FUNDS_USAGE_NOT_EXPENSE")));
   b.addValue("projectKey",projectKey);jdbc.update("insert into fc_budget_usage(tenant_id,policy_id,source_kind,source_id,amount,state,snapshot"+(dimensional?",project_key":"")+") values(:tenant,:policy,:kind,:source,:amount,'INFLIGHT',cast(:snapshot as jsonb)"+(dimensional?",:projectKey":"")+") on conflict(tenant_id,policy_id,source_kind,source_id) do update set amount=excluded.amount,state='INFLIGHT',snapshot=excluded.snapshot"+(dimensional?",project_key=excluded.project_key":"")+",updated_at=now()",b);guard.event(p,hotel,kind,sourceId,exceeded?"BUDGET_WARNING":"BUDGET_RESERVED",map(b.getValue("snapshot")));
  }
 }
 /** Rebuild only this claim's active reservation from the finance-confirmed facts in the caller's review transaction. */
 void revalidateClaimApproval(TenantPrincipal p,UUID claimId){
  if(!guard.installed())return;
  var b=base(p).addValue("source",claimId);
  var source=jdbc.queryForMap("select * from finance_claim where tenant_id=:tenant and id=:source for update",b);
  if(!"FINANCE_REVIEW".equals(source.get("status"))||source.get("approved_amount")==null)throw conflict("财务预算复核须使用当前待财务审核单据的已确认金额");
  jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,103))",base(p).addValue("key",p.tenantId()+":financial-budget"),Object.class);
  var previous=jdbc.queryForList("select policy_id,amount::text,state from fc_budget_usage where tenant_id=:tenant and source_kind='CLAIM' and source_id=:source and state<>'RELEASED' order by policy_id",b);
  jdbc.update("update fc_budget_usage set state='RELEASED',updated_at=now() where tenant_id=:tenant and source_kind='CLAIM' and source_id=:source and state<>'RELEASED'",b);
  // Keep the original request immutable; reserve() uses this copy solely as the effective approved budget basis.
  var approved=new LinkedHashMap<String,Object>(source);approved.put("requested_amount",source.get("approved_amount"));
  reserve(p,"CLAIM",approved);
  guard.event(p,id(source.get("hotel_id")),"CLAIM",claimId,"BUDGET_APPROVAL_REVALIDATED",Map.of("approvedAmount",amount(source.get("approved_amount")).toPlainString(),"categoryId",source.get("category_id"),"businessDate",source.get("business_date").toString(),"previousUsage",previous));
 }
 void transition(TenantPrincipal p,String kind,Map<String,Object> source,String state){if(!guard.installed())return;jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,103))",base(p).addValue("key",p.tenantId()+":financial-budget"),Object.class);UUID sourceId=id(source.get("id"));var b=base(p).addValue("kind",kind).addValue("source",sourceId);var policies=jdbc.queryForList("select p.id from fc_policy p join fc_budget_usage u on u.tenant_id=p.tenant_id and u.policy_id=p.id where u.tenant_id=:tenant and u.source_kind=:kind and u.source_id=:source order by p.id for update of p",b);if(policies.isEmpty())return;
  String next=Set.of("RETURNED","REJECTED","CANCELLED","WITHDRAWN").contains(state)?"RELEASED":state.equals("APPROVED")?kind.equals("OPERATION")&&"CONTRACT".equals(source.get("type"))?"COMMITTED":"ACTUAL":"INFLIGHT";jdbc.update("update fc_budget_usage set state=:state,updated_at=now() where tenant_id=:tenant and source_kind=:kind and source_id=:source and (:kind<>'CLAIM' or :state='RELEASED' or state<>'RELEASED')",b.addValue("state",next));guard.event(p,id(source.get("hotel_id")),kind,sourceId,"BUDGET_"+next,Map.of("sourceStatus",state));}
 void cash(TenantPrincipal p,Map<String,Object> instruction,Map<String,Object> source){if(!guard.installed())return;LocalDate day=LocalDate.parse(instruction.get("occurred_on").toString());String action=instruction.get("action").toString();String direction=Set.of("RECEIPT","REPAYMENT").contains(action)||action.equals("REFUND")&&!"REVENUE".equals(source.get("type"))?"IN":"OUT";
  var b=base(p).addValue("hotel",instruction.get("hotel_id")).addValue("day",day);var plans=jdbc.queryForList("select * from fc_policy where tenant_id=:tenant and hotel_id=:hotel and kind='CASH_PLAN' and status='PUBLISHED' and effective_from<=:day and (effective_to is null or effective_to>=:day) order by id for update",b);
  for(var plan:plans){var spec=map(plan.get("spec"));if(!YearMonth.from(day).toString().equals(spec.get("month"))||!direction.equals(spec.get("direction")))continue;LocalDate start=YearMonth.from(day).atDay(1);BigDecimal total=new FinanceCashPlanTotals(jdbc).total(p,id(instruction.get("hotel_id")),YearMonth.from(day),direction);boolean over=total.add(amount(instruction.get("amount"))).compareTo(amount(spec.get("amount")))>0;
   if(over&&"BLOCK".equals(spec.get("control")))throw conflict("本月资金计划超额，先复核计划修订再登记；这不是费用预算余额");if(over)guard.event(p,id(instruction.get("hotel_id")),"CASH_INSTRUCTION",id(instruction.get("id")),"CASH_PLAN_WARNING",Map.of("policyId",plan.get("id"),"spec",spec));
  }
 }
}
